<template>
  <div class="code-editor-container">
    <codemirror
      ref="codeEditor"
      v-model="editorContent"
      :options="editorOptions"
      class="code-editor"
      @ready="onEditorReady"
    ></codemirror>
  </div>
</template>

<script>
import "codemirror/lib/codemirror.css";
import "codemirror/theme/monokai.css";
import "codemirror/mode/javascript/javascript";
import { codemirror } from "vue-codemirror";

export default {
  name: "LockedFunctionEditor",
  components: {
    codemirror,
  },
  props: {
    functionName: {
      type: String,
      required: true,
      default: "",
    },
    echoCode: {
      type: String,
      default: "",
    },
  },
  data() {
    return {
      editorContent: "",
      editorOptions: {
        mode: "javascript",
        theme: "monokai",
        lineNumbers: true,
        readOnly: false, // 整体可编辑，仅锁定指定区域
        indentUnit: 2,
      },
      userScript: "",
      // 存储只读标记，用于更新函数名时清除旧标记
      readOnlyMarks: [],
    };
  },
  watch: {
    functionName: {
      immediate: true,
      handler(newName) {
        this.initEditorTemplate(newName);
        // 函数名变化时，重新锁定只读区域
        this.$nextTick(() => this.lockFunctionShell());
      },
    },
    editorContent(newContent) {
      this.extractUserScript(newContent);
    },
  },
  methods: {
    // 初始化编辑器模板
    initEditorTemplate(funcName) {
      let template;
      if (this.echoCode && this.echoCode.includes(`function ${funcName}()`)) {
        template = this.echoCode;
      } else {
        // 2. 无回显代码，使用默认模板
        template = `function ${funcName}() {
  // 添加脚本
  
};`;
      }
      this.editorContent = template;
    },

    // 编辑器初始化完成后执行
    onEditorReady() {
      this.lockFunctionShell();
    },

    /**
     * 核心：锁定函数外壳为只读（函数名、{、}; 都不可编辑）
     */
    lockFunctionShell() {
      const editor = this.$refs.codeEditor.codemirror;
      if (!editor) return;

      // 先清除旧的只读标记，避免重复锁定
      this.readOnlyMarks.forEach((mark) => mark.clear());
      this.readOnlyMarks = [];

      const content = editor.getValue();
      const funcName = this.functionName;

      // 1. 锁定开头：function addnum() {
      const startStr = `function ${funcName}() {`;
      const startIndex = content.indexOf(startStr);
      if (startIndex > -1) {
        const startPos = editor.posFromIndex(startIndex);
        const endPos = editor.posFromIndex(startIndex + startStr.length);
        // 标记为只读，且样式高亮（可选）
        const mark1 = editor.markText(startPos, endPos, {
          readOnly: true,
          className: "locked-region", // 自定义只读区域样式
        });
        this.readOnlyMarks.push(mark1);
      }

      // 2. 锁定结尾：};
      const endStr = "};";
      const endIndex = content.lastIndexOf(endStr);
      if (endIndex > -1) {
        const startPos = editor.posFromIndex(endIndex);
        const endPos = editor.posFromIndex(endIndex + endStr.length);
        const mark2 = editor.markText(startPos, endPos, {
          readOnly: true,
          className: "locked-region",
        });
        this.readOnlyMarks.push(mark2);
      }

      // 3. 自动聚焦到可编辑区域（函数内部）
      const editStartIndex = startIndex + startStr.length + 1;
      editor.setCursor(editor.posFromIndex(editStartIndex));
    },

    // 提取用户编辑的函数体
    extractUserScript(content) {
      const reg = new RegExp(
        `function ${this.functionName}\\(\\) \\{([\\s\\S]*?)\\};`,
        "g",
      );
      const match = reg.exec(content);
      this.userScript = match?.[1]?.trim() || "";
      console.log(this.editorContent);
    },
  },
};
</script>

<style scoped>
.code-editor-container {
  width: 100%;
}

.code-editor {
  height: 100%;
  border-radius: 4px;
}

/* 给只读区域加样式（可选，方便用户区分） */
::v-deep .locked-region {
  background: #333;
  color: #ccc;
  cursor: not-allowed;
}
::v-deep .CodeMirror {
  height: 100%;
  margin: 0 !important;
  line-height:20px !important;

}
</style>
