<template>
  <div v-if="showPage">
    <el-button
      type="primary"
      plain
      icon="el-icon-plus"
      size="mini"
      @click="addRules"
      >新增函数</el-button
    >
    <el-table class="mt-10" :data="functionScriptListList" style="width: 100%">
      <el-table-column label="序号">
        <template slot-scope="scope">{{ scope.$index + 1 }}</template>
      </el-table-column>
      <el-table-column prop="name" label="函数名称"> </el-table-column>
      <el-table-column prop="remarks" label="描述"> </el-table-column>
      <el-table-column label="操作">
        <template slot-scope="scope">
          <el-button
            type="text"
            icon="el-icon-edit"
            @click="editData(scope.row)"
          />
          <el-button type="text" @click="association(scope.row)">
            <i title="配置" class="el-icon-setting"></i>
          </el-button>
          <el-button type="text" @click="delData(scope.row)">
            <i title="删除" class="el-icon-delete" style="color: red"></i>
          </el-button>
        </template>
      </el-table-column>
    </el-table>
    <el-dialog
      :title="title"
      :visible.sync="addVisible"
      width="50%"
      :close-on-click-modal="false"
      top="10px"
      :rules="rules"
    >
      <el-form
        :model="addForm"
        ref="addForm"
        :rules="rules"
        label-width="120px"
        class="mt-20"
      >
        <el-form-item label="函数名称:" prop="name">
          <el-input
            v-model="addForm.name"
            style="width: 60%"
            :disabled="!!addForm.id"
          ></el-input>
          <div style="font-size: 12px">只能包含字母。长度在1-64之间。</div>
        </el-form-item>
        <el-form-item label="描述:" prop="remarks">
          <el-input v-model="addForm.remarks" style="width: 60%"></el-input>
        </el-form-item>
      </el-form>
      <span slot="footer" class="dialog-footer">
        <el-button @click="addVisible = false">取 消</el-button>
        <el-button type="primary" @click="submitForm('addForm')"
          >确 定</el-button
        >
      </span>
    </el-dialog>
  </div>
  <div v-else class="configure">
    <el-page-header @back="showPage = true" :content="configure.name">
    </el-page-header>
    <el-form :model="addForm" ref="addForm" :rules="rules">
      <el-form-item label="脚本:" prop="scripts">
        <functionEditor
          ref="functionEditor"
          :functionName="configure.name"
          style="height: 55vh"
          :echoCode="echoCode"
        />
      </el-form-item>
      <el-form-item class="c-align">
        <el-button size="small" @click="submit('addForm')"
          >提交</el-button
        ></el-form-item
      >
    </el-form>
  </div>
</template>

<script>
import { rules } from "@/assets/utils/config";
import functionEditor from "@/components/functionEditor.vue";

export default {
  data() {
    const validateLong = (rule, value, callback) => {
      const reg = /^.{1,64}$/;
      if (!reg.test(value)) {
        callback(new Error("长度需在1-64之间！"));
      } else {
        callback();
      }
    };
    return {
      functionScriptListList: [],
      addForm: {},
      addVisible: false,
      title: "新增函数",
      rules: {
        name: [
          { required: true, message: "请输入", trigger: "blur" },
          { validator: rules.validateStr, trigger: "change" },
          { validator: validateLong, trigger: "change" },
        ],
        scripts: [{ required: true, message: "请输入", trigger: "blur" }],
      },
      showPage: true,
      echoCode: "",
    };
  },

  components: {
    functionEditor,
  },
  created() {
    this.getData();
  },
  methods: {
    getData() {
      this.$api.get(`/rules/getFunctionScriptList`).then((res) => {
        if (res.data.data) {
          this.functionScriptListList = res.data.data;
        }
      });
    },
    editData(item) {
      this.title = "编辑场景";
      this.addForm = { ...item };
      this.addVisible = true;
    },
    association(item) {
      this.configure = item;
      this.echoCode = this.configure.scripts;
      this.showPage = false;
    },
    delData(item) {
      this.$confirm("是否删除该数据?", "提示", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning",
      })
        .then(() => {
          this.$api
            .post("/rules/delFunctionScript", {
              id: item.id,
            })
            .then(() => {
              this.$message.success("操作成功");
              this.getData();
            });
        })
        .catch(() => {
          this.$message({
            type: "info",
            message: "已取消删除",
          });
        });
    },
    submitForm(formName) {
      this.$refs[formName].validate((valid) => {
        if (valid) {
          let url = this.addForm.id
            ? "/rules/updateFunctionScript"
            : "/rules/addFunctionScript";
          this.$api.post(url, this.addForm).then(() => {
            this.addVisible = false;
            this.$message.success("操作成功");
            this.getData();
          });
        } else {
          return false;
        }
      });
    },
    submit() {
      let data = {
        ...this.configure,
        scripts: this.$refs.functionEditor.editorContent,
      };
      this.$api.post("/rules/updateFunctionScript", data).then(() => {
        this.addVisible = false;
        this.$message.success("操作成功");
        this.getData();
      });
    },
    addRules() {
      this.title = "新增函数";
      this.addForm = {};
      this.addVisible = true;
    },
  },
};
</script>

<style lang="scss" scoped>
::v-deep .el-page-header__content {
  font-size: 16px !important;
}

.configure {
  ::v-deep .el-form-item--small {
    margin-bottom: 0 !important;
    width: 100% !important;
  }
}
::v-deep .el-form-item--small .el-form-item__content {
  width: 100% !important;
}
::v-deep .condition {
  border: 1px solid #e4e4e4;
  margin-bottom: 10px;
  .el-select {
    width: 100%;
  }
  .header {
    background: #fafafa;
    padding: 10px;
    display: flex;
    justify-content: space-between;
    border-bottom: 1px solid #e4e4e4;
    font-size: 14px;
  }
}
</style>
